import { isDateString } from "./isDateString";
export const convertDates = (data, toLocalDateTime) => {
    for (let i = 0; i < data.datasets.length; i++) {
        const ds = data.datasets[i].data;
        for (let j = 0; j < ds.length; j++) {
            const point = ds[j];
            if (typeof point === "object" && typeof point.x === "string" && isDateString(point.x)) {
                ds[j] = Object.assign(Object.assign({}, point), { x: toLocalDateTime(point.x) });
                continue;
            }
        }
    }
    return data;
};
